22	const BASE_PRICE_BY_TYPE: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const FIRST_INSURANCE_MULTIPLIER = 1.1;
32	const CONTRACT_FEE = 5;
33	
34	const BUILDING_BLOCK_SIZE = 3;
35	const BUILDING_BLOCK_BASE_PRICE = 60;
36	
37	const CURSED_MULTIPLIER = 1.5;
38	const HIGH_ENCHANTMENT_LEVEL = 5;
39	const HIGH_ENCHANTMENT_MULTIPLIER = 1.3;
40	
41	// Risk surcharges apply per item, before the contract-level multiplier and fee.
42	const riskAdjustedPriceOfItem = (item: Item): number =>
43	  BASE_PRICE_BY_TYPE[item.type] *
44	  (item.cursed ? CURSED_MULTIPLIER : 1) *
45	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_MULTIPLIER : 1);
46	
47	const sumOfIndividualPrices = (items: Item[]): number =>
48	  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);
49	
50	// "Alike" in the price list means same type — material and enchantment do not
51	// affect whether components group into a building block.
52	const groupByType = (items: Item[]): Item[][] => {
53	  const groups = new Map<string, Item[]>();
54	
55	  for (const item of items) {
56	    const group = groups.get(item.type);
57	    if (group) group.push(item);
58	    else groups.set(item.type, [item]);
59	  }
60	
61	  return [...groups.values()];
62	};
63	
64	// Every three alike components form a building block priced at 60 G; the
65	// remainder of the group is priced individually.
66	const basePriceOfAlikeGroup = (group: Item[]): number => {
67	  const blocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
68	  const leftovers = group.slice(blocks * BUILDING_BLOCK_SIZE);
69	
70	  return blocks * BUILDING_BLOCK_BASE_PRICE + sumOfIndividualPrices(leftovers);
71	};
72	
73	const basePriceOf = (items: Item[]): number =>
74	  groupByType(items).reduce(
75	    (total, group) => total + basePriceOfAlikeGroup(group),
76	    0,
77	  );
78	
79	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
80	// no test yet lands on a half-way value, so the rounding *direction* stays
81	// unspecified until the "rounds in MHPCO's favor" test pins it.
82	const quoteStep = (step: Step): StepResult => ({
83	  premium:
84	    Math.round(basePriceOf(step.items!) * FIRST_INSURANCE_MULTIPLIER) + CONTRACT_FEE,
85	});
86	
87	export const runScenario = (scenario: Scenario): ScenarioResult => ({
88	  results: scenario.steps.map(quoteStep),
89	});
