const CURSED_MULTIPLIER = 1.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_MULTIPLIER = 1.3;

// Each surcharge multiplies the base price when its condition holds. They
// compose multiplicatively, so an item matching several pays all of them.
const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; multiplier: number }[] = [
  { appliesTo: (item) => item.cursed === true, multiplier: CURSED_MULTIPLIER },
  {
    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
    multiplier: HIGH_ENCHANTMENT_MULTIPLIER,
  },
];

// Risk surcharges apply per item, before the contract-level multiplier and fee.
const riskAdjustedPriceOfItem = (item: Item): number =>
  RISK_SURCHARGES.reduce(
    (price, surcharge) =>
      surcharge.appliesTo(item) ? price * surcharge.multiplier : price,
    BASE_PRICE_BY_TYPE[item.type],
  );
